import { ReactNode, useRef, useState, useEffect, useMemo } from 'react';

const cssDefinitions = `
    .no-scrollbar::-webkit-scrollbar {
        display: none;
    }
`;

const Tile = ({
    src,
    colNumber
}: {
    src: string;
    colNumber: number;
}): JSX.Element => (
    <div
        style={{
            position: 'relative',
            height: 'calc(50% - 1.5em)',
            width: 'calc(100% - 1.25em)',
            margin: `1em 0 1em ${1 - colNumber * 0.25}em`
        }}
    >
        <div
            // TODO p.kubala find the way to get rid of test-id
            data-testid="imageTile"
            style={{
                backgroundColor: 'grey',
                backgroundImage: `url(${src})`,
                backgroundPosition: 'center center',
                backgroundSize: 'cover',
                width: '100%',
                height: '100%'
            }}
        />
    </div>
);

const Column = ({ children }: { children: ReactNode }): JSX.Element => (
    <div
        style={{
            height: '100%',
            flex: '0 0 auto',
            scrollSnapAlign: 'start',
            width: '25%'
        }}
    >
        {children}
    </div>
);

const Images = ({
    data = [],
    scrollIntervalMs,
    scroll,
    loadColumns
}: {
    scroll: number;
    data?: { id: string; thumbnailUrl?: string }[];
    scrollIntervalMs: number;
    loadColumns: number;
}): JSX.Element => {
    const pairsContainerRef = useRef<HTMLDivElement>(null);
    const [shift, setShift] = useState<number>(0);
    const dataLength = data.length;

    const transitionDurationS = useMemo(() => {
        const newTransitionDuration = Math.floor(scrollIntervalMs / 1000) / 2;
        return newTransitionDuration > 2 ? 2 : newTransitionDuration;
    }, [scrollIntervalMs]);

    useEffect(() => {
        let timeOut: NodeJS.Timeout;
        const interval = setInterval(() => {
            const element = pairsContainerRef.current;
            const fBox = element?.firstChild?.firstChild;
            const fImage = fBox?.firstChild;

            if (!element || !fBox || !fImage) {
                return;
            }

            const calcLeft = getComputedStyle(fBox as Element).getPropertyValue(
                'margin-left'
            );
            const marginLeft = (String(calcLeft as string) || '16').match(
                /\d+(?:.\d+)?/gi
            );
            const ml =
                Array.isArray(marginLeft) && marginLeft.length
                    ? marginLeft[0]
                    : '16';
            const toLeft =
                Number((fImage as HTMLDivElement)?.offsetWidth) + Number(ml);

            element?.style.setProperty(
                'transition',
                `${transitionDurationS}s transform linear`
            );
            element?.style.setProperty('transform', `translateX(-${toLeft}px)`);

            const finalStep = () => {
                element?.style.removeProperty('transform');
                element?.style.removeProperty('transition');
                setShift((oldShift) => (oldShift + scroll) % dataLength);
            };

            timeOut = setTimeout(() => {
                window.requestAnimationFrame(finalStep);
            }, transitionDurationS * 1500);
        }, scrollIntervalMs);

        return () => {
            clearInterval(interval);
            clearTimeout(timeOut);
        };
    }, [dataLength, pairsContainerRef.current, transitionDurationS]);

    return (
        <>
            <style>{cssDefinitions}</style>
            <div
                style={{
                    height: '100%',
                    width: '100%',
                    overflow: 'hidden'
                }}
            >
                <div
                    ref={pairsContainerRef}
                    // TODO p.kubala find the way to get rid of test-id
                    data-testid="pairsContainer"
                    className="no-scrollbar"
                    style={{
                        height: '100%',
                        display: 'flex',
                        flexWrap: 'nowrap'
                    }}
                >
                    {data.length &&
                        new Array(loadColumns).fill(0).map((e, i) => {
                            const col = e + i;
                            const colShift = 2 * col + shift;
                            const tile1Shift = colShift % dataLength;
                            const tile2Shift = (colShift + 1) % dataLength;
                            const columnKey = `${col}_${data[tile1Shift].id}_${data[tile2Shift].id}`;

                            return (
                                <Column key={columnKey}>
                                    <Tile
                                        key={`${col}_${data[tile1Shift].id}`}
                                        src={
                                            data[tile1Shift]
                                                .thumbnailUrl as string
                                        }
                                        colNumber={col}
                                    />
                                    <Tile
                                        key={`${col}_${data[tile2Shift].id}`}
                                        src={
                                            data[tile2Shift]
                                                .thumbnailUrl as string
                                        }
                                        colNumber={col}
                                    />
                                </Column>
                            );
                        })}
                </div>
            </div>
        </>
    );
};

export default Images;
