/* eslint-disable @typescript-eslint/no-unused-vars */
/* eslint-disable functional/no-return-void */
/* eslint-disable class-methods-use-this */

import {
    WidgetState,
    ReadyStateValue,
    NetworkStateValue
} from './widget-state';

export abstract class SupernovaWidget extends HTMLElement {
    protected emotionRoot: HTMLStyleElement;

    protected mountPoint: HTMLDivElement;

    private readonly widgetState: WidgetState;

    protected getReadyState(): string {
        return this.widgetState.getReadyState();
    }

    protected getReadyStateValue(): number {
        return this.widgetState.getReadyStateValue();
    }

    // eslint-disable-next-line functional/no-return-void
    protected setReadyState(newReadyState: ReadyStateValue): void {
        this.widgetState.setReadyState(newReadyState);
    }

    protected getNetworkState(): string {
        return this.widgetState.getNetworkState();
    }

    protected getNetworkStateValue(): number {
        return this.widgetState.getNetworkStateValue();
    }

    // eslint-disable-next-line functional/no-return-void
    protected setNetworkState(newNetworkState: NetworkStateValue): void {
        this.widgetState.setNetworkState(newNetworkState);
    }

    constructor() {
        super();
        this.widgetState = new WidgetState();
        this.emotionRoot = document.createElement('style');
        this.mountPoint = document.createElement('div');
    }

    protected readyToPlay: boolean | null = null;

    protected onReady = (): unknown => null;

    protected readyWasReported = false;

    protected abstract reportReady(): void;

    protected abstract initialize(): void;

    static observedAttributes: Array<unknown> = [];

    abstract play(): void;

    abstract pause(): void;

    protected abstract attributeChangedCallback(
        name: string,
        oldValue: string,
        newValue: string
    ): void;

    protected abstract connectedCallback(): void;
}
