import { ThemeOptions } from '@mui/material/styles';

import { Animation } from './animation';
import { Api, isApi } from './api';
import { ContainerQueriesThemeOptions } from './container-queries-theme-options';
import { DisplayMode, isDisplayMode } from './display-mode';

export type WidgetConfig = Readonly<{
    api: Readonly<Api>;
    autoplaySpeed?: number;
    displayMode?: Readonly<DisplayMode>;
    intro?: string;
    name?: string;
    theme?: Readonly<ThemeOptions & ContainerQueriesThemeOptions>;
    animation: Readonly<Animation>;
    autoplay?: boolean;
    volume?: number;
    zeroPostsText?: string;
    canvasConfig?: Readonly<{ content: { keyword: string } }>;
    showThumbnail: boolean;
}>;

export const isWidgetConfig = (value: unknown): value is WidgetConfig =>
    !!value &&
    isApi((value as WidgetConfig).api) &&
    ((value as WidgetConfig).autoplaySpeed === undefined ||
        typeof (value as WidgetConfig).autoplaySpeed === 'number') &&
    ((value as WidgetConfig).autoplay === undefined ||
        typeof (value as WidgetConfig).autoplay === 'boolean') &&
    ((value as WidgetConfig).displayMode === undefined ||
        isDisplayMode((value as WidgetConfig).displayMode)) &&
    ((value as WidgetConfig).intro === undefined ||
        typeof (value as WidgetConfig).intro === 'string') &&
    ((value as WidgetConfig).name === undefined ||
        typeof (value as WidgetConfig).name === 'string');
