import { ReactNode } from 'react';
import { ThemeOptions, ThemeProvider, createTheme } from '@mui/material/styles';
import { CacheProvider } from '@emotion/react';
import createCache from '@emotion/cache';
import { muiThemeCustomDefaults } from './mui-theme-custom-defaults';

export const MuiProvider = ({
    children,
    emotionRoot,
    themeOptions
}: {
    children: ReactNode;
    emotionRoot: HTMLStyleElement;
    themeOptions?: ThemeOptions;
}): JSX.Element => {
    const cache = createCache({
        key: 'supernova-sns',
        prepend: true,
        container: emotionRoot // TODO frameEl ? frameEl.contentDocument?.head :
    });

    return (
        <CacheProvider value={cache}>
            <ThemeProvider
                theme={createTheme({
                    ...muiThemeCustomDefaults,
                    ...themeOptions
                })}
            >
                {children}
            </ThemeProvider>
        </CacheProvider>
    );
};
