import { createContext, useState, ReactNode } from 'react';
import {
    SnsError,
    WidgetErrorState,
    initialWidgetErrorState,
    initialSnsError
} from '../types/widget-error';

export const ErrorContext = createContext<SnsError>(initialSnsError);

export const ErrorProvider = ({
    children
}: Readonly<{
    children: ReactNode;
}>): JSX.Element => {
    const [errorState, setErrorState] = useState<WidgetErrorState>(
        initialWidgetErrorState
    );

    const updateError = (newErrorState: WidgetErrorState): void => {
        setErrorState(newErrorState);
    };
    return (
        <ErrorContext.Provider
            value={{ errorState, updateErrorState: updateError }}
        >
            {children}
        </ErrorContext.Provider>
    );
};
