import { SnsPost, isSnsPost } from '../types/sns-post';

const localStorageKey = 'snsPosts';

export const getPostsFromLocalStorage = (): SnsPost[] | undefined => {
    const stringifiedItems = window.localStorage.getItem(localStorageKey);

    if (!stringifiedItems) return undefined;

    const updatedItems = JSON.parse(stringifiedItems).filter(
        isSnsPost
    ) as SnsPost[];

    return updatedItems;
};

export const storePostsInLocalStorage = (posts: readonly SnsPost[]): void => {
    localStorage.setItem(localStorageKey, JSON.stringify(posts));
};
