import { Card, CardMedia } from '@mui/material';
import DefaultHeader from '../../components/default-header';
import DefaultDetails from '../../components/default-details';
import InstagramDisabled from '../../assets/images/Instagram_disabled.svg';
import ErrorMark from '../../assets/images/img_error_mark.svg';

type ErrorPageParams = Readonly<{
    errorText: string;
    logo: string;
    title: string;
    hasFullWidth: boolean;
}>;

const ErrorPage = ({
    errorText,
    logo = '',
    title,
    hasFullWidth
}: ErrorPageParams): JSX.Element => (
    <Card>
        <DefaultHeader
            logo={logo}
            headerText={title}
            hasFullWidth={hasFullWidth}
        />
        <DefaultDetails
            hasFullWidth={hasFullWidth}
            imageComponent={
                <div
                    style={{
                        position: 'relative'
                    }}
                >
                    <CardMedia
                        component="img"
                        image={
                            process.env.NODE_ENV === 'development'
                                ? // eslint-disable-next-line global-require
                                  require('../../assets/images/Instagram_disabled.svg')
                                : InstagramDisabled
                        }
                        sx={{
                            maxWidth: '100%',
                            marginTop: '0',
                            height: 'auto',
                            margin: 'auto'
                        }}
                    />
                    <div
                        style={{
                            position: 'absolute',
                            top: 0,
                            left: 0,
                            width: `100%`,
                            height: `100%`,
                            backgroundColor: 'rgba(0, 0, 0, 0.5)'
                        }}
                    />
                    <CardMedia
                        component="img"
                        image={
                            process.env.NODE_ENV === 'development'
                                ? // eslint-disable-next-line global-require
                                  require('../../assets/images/img_error_mark.svg')
                                : ErrorMark
                        }
                        sx={{
                            width: '24%',
                            height: '24%',
                            position: 'absolute',
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)'
                        }}
                    />
                </div>
            }
            detailsText={errorText}
            fontColor="#f75b5b"
        />
    </Card>
);

export default ErrorPage;
