import { UseQueryResult } from 'react-query';

type Sns = { type: string; logoSrc: string };

export type SnsLogoResult = UseQueryResult<string>;

export type SnsPostResult = UseQueryResult<SnsPost[]>;

type Media = {
    type: /* 'CAROUSEL_ALBUM' | */ 'IMAGE' | 'VIDEO';
    fileSrc: string;
};

const isMedia = (value: unknown): value is Media =>
    !!value &&
    typeof value === 'object' &&
    ['IMAGE', 'VIDEO'].includes((value as Media).type) &&
    typeof (value as Media).fileSrc === 'string';

const isSns = (value: unknown): value is Sns =>
    !!value &&
    typeof value === 'object' &&
    typeof (value as Sns).type === 'string' &&
    typeof (value as Sns).logoSrc === 'string';

export type User = { name: string; profileImageSrc: string };

const isUser = (value: unknown): value is User =>
    !!value &&
    typeof value === 'object' &&
    typeof (value as User).name === 'string' &&
    typeof (value as User).profileImageSrc === 'string';

export type SnsPost = Readonly<{
    id: string;
    created: string;
    hashtag: string;
    likeCount: number;
    text: string;
    thumbnailUrl?: string;
    media: Readonly<Media>;
    sns: Readonly<Sns>;
    user: Readonly<User>;
}>;

export const isSnsPost = (value: unknown): value is SnsPost =>
    !!value &&
    typeof value === 'object' &&
    typeof (value as SnsPost).id === 'string' &&
    typeof (value as SnsPost).created === 'string' &&
    typeof (value as SnsPost).hashtag === 'string' &&
    typeof (value as SnsPost).likeCount === 'number' &&
    (value as SnsPost).likeCount >= 0 &&
    typeof (value as SnsPost).text === 'string' &&
    ['undefined', 'string'].includes(typeof (value as SnsPost).thumbnailUrl) &&
    isMedia((value as SnsPost).media) &&
    isSns((value as SnsPost).sns) &&
    isUser((value as SnsPost).user);
