export type DisplayMode = 'MULTI' | 'SINGLE' | 'SPLASH_SCREEN';

export const isDisplayMode = (value: unknown): value is DisplayMode =>
    ['MULTI', 'SINGLE', 'SPLASH_SCREEN'].includes(value as string);
