import { ReactNode, createContext, useContext } from 'react';

const ContainerQueriesBreakpointContext = createContext<number | undefined>(
    undefined
);

export const ContainerQueriesBreakpointProvider = ({
    children,
    value
}: {
    children: ReactNode;
    value: number | undefined;
}): JSX.Element => (
    <ContainerQueriesBreakpointContext.Provider value={value}>
        {children}
    </ContainerQueriesBreakpointContext.Provider>
);

export const useContainerQueriesBreakpoint = (): number | undefined => {
    const context = useContext(ContainerQueriesBreakpointContext);
    if (context === undefined) {
        /* eslint-disable-next-line functional/no-throw-statement */
        throw new Error(
            'useContainerQueriesBreakpoint must be used within a ContainerQueriesBreakpointProvider'
        );
    }
    return context;
};
