import { keyframes } from '@emotion/react';
import { tap, timer } from 'rxjs';
import { PostAnimationType } from '../constants';

/* istanbul ignore next */
export const animationStyles = {
    [PostAnimationType.translationX]: {
        shownPostStyle: {
            transform: 'none',
            opacity: 1,
            zIndex: 5000,
            animation: 'none'
        },
        hiddenPostStyle: {
            transform: 'translateX(100%)',
            opacity: 1,
            zIndex: 4000,
            animation: 'none'
        },
        animationShownPost: (duration: number): string =>
            `${keyframes`
                from {
                    transform: translateX(0%);
                }
                to {
                    transform: translateX(-100%);
                }`} ${duration}ms 1 linear forwards`,
        animationHiddenPost: (duration: number): string =>
            `${keyframes`
                from {
                    transform: translateX(100%);
                }
                to {
                    transform: translateX(0%);
                }`} ${duration}ms 1 linear forwards`
    },
    [PostAnimationType.none]: {
        shownPostStyle: {
            transform: 'none',
            opacity: 1,
            zIndex: 5000,
            animation: 'none'
        },
        hiddenPostStyle: {
            transform: 'none',
            opacity: 1,
            zIndex: 4000,
            animation: 'none'
        },
        animationShownPost: (): string => '',
        animationHiddenPost: (): string => ''
    },
    [PostAnimationType.opacity]: {
        shownPostStyle: {
            transform: 'none',
            opacity: 1,
            zIndex: 5000,
            animation: 'none'
        },
        hiddenPostStyle: {
            transform: 'none',
            opacity: 1,
            zIndex: 4000,
            animation: 'none'
        },
        animationShownPost: (): string => '',
        animationHiddenPost: (): string => ''
    },
    [PostAnimationType.translationY]: {
        // not implemented/used but similar to translateX if we need it
        shownPostStyle: {},
        hiddenPostStyle: {},
        animationShownPost: (): string => '',
        animationHiddenPost: (): string => ''
    }
};

/* istanbul ignore next */
export const animationStyleOpacity = {
    disappear: (duration: number): string =>
        `${keyframes`
        0% {
            opacity: 0;
        }
        40% {
            opacity: 0;
        }
        100% {
            opacity: 1;
        }
        `} ${duration}ms 1 linear forwards`,
    appear: (duration: number): string =>
        `${keyframes`
        0% {
            opacity: 1;
        }
        50% {
            opacity: 1;
        }
        100% {
            opacity: 0;
        }
        `} ${duration}ms 1 linear forwards`,
    static: {
        transform: 'none',
        opacity: 0,
        zIndex: 25000,
        animation: 'none'
    }
};

export const getTimer$ = (durationMs: number, callback: () => void) =>
    timer(durationMs).pipe(tap(() => requestAnimationFrame(callback)));
