import { CSSProperties } from 'react';
import { TData } from '../../types/sns-card-types';

export const contentBoxStylesheet = (props: { hasFullWidth: boolean }) => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: props.hasFullWidth ? '0.5vw 0.5vw 0 0.5vw' : '1vh 1vh 0 1vh'
});

export const snsCardContentStylesheet = () => {
    const attributes: CSSProperties = {
        textAlign: 'justify',
        padding: '0',
        paddingTop: '10%'
    };
    return {
        shouldForwardProp: (prop: string) => prop !== 'sx',
        ...attributes
    };
};

export const topContentBoxStylesheet = {
    overflow: 'hidden'
};

export const bottomContentBoxStyleSheet = {
    display: 'flex',
    alignItems: 'flex-end'
};

export const mainBoxStylesheet = () => {
    const attributes: CSSProperties = {
        position: 'relative',
        overflow: 'hidden',
        height: '100%'
    };
    return {
        ...attributes
    };
};

export const backgroundCardStylesheet = (props: {
    styleModification: CSSProperties;
}) => {
    const attributes: CSSProperties = {
        ...{
            height: '100%',
            width: '100%',
            display: 'flex',
            position: 'absolute'
        },
        ...props.styleModification
    };
    return { ...attributes };
};

const boxShadow = {
    WebkitBoxShadow: '0px 0px 20px 0px rgba(0,0,0,0.5)',
    MozBoxShadow: '0px 0px 20px 0px rgba(0,0,0,0.5)',
    boxShadow: '0px 0px 20px 0px rgba(0,0,0,0.5)'
};

export const getMediaStyle = (
    contentType: 'IMAGE' | 'VIDEO',
    addBoxShadow: boolean
): CSSProperties => {
    const mediaStyle: CSSProperties = {
        position: 'absolute',
        top: 0,
        left: 0,
        bottom: 0,
        right: 0,
        margin: 'auto',
        width: 'auto',
        height: 'auto',
        maxHeight: contentType === 'IMAGE' ? '85%' : '90%',
        maxWidth: '85%'
    };
    return addBoxShadow ? { ...mediaStyle, ...boxShadow } : { ...mediaStyle };
};

