export const classesCss = (hasFullWidth: boolean) => `
.MuiPaper-rounded {
    border-radius: 0px;
    box-shadow: none;
    -webkit-border-radius: 0px;
    -khtml-border-radius: 0px;
    -moz-border-radius: 0px;
    -ms-border-radius: 0px;
    -o-border-radius: 0px;
    -webkit-box-shadow: none;
    -khtml-box-shadow: none;
    -moz-box-shadow: none;
    -ms-box-shadow: none;
    -o-box-shadow: none;
}
.sns-card-left,
.sns-card-right {
    height: 100%;
}

.sns-card-left {
    width: 49%;
    padding: ${hasFullWidth ? '3vw 3vw 0 3vw' : '6vh 6vh 0 6vh'};
}

.sns-card-right {
    width: 51%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: ${hasFullWidth ? '3vw 6.5vw 3vw 3.5vw' : '6vh 13vh 6vh 7vh'};
}`;

export const introLoaderStylesheet = (
    loaderDimension: string,
    backgroundSize: string,
    imageUrl: string
): CSSProperties => ({
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: loaderDimension,
    height: loaderDimension,
    fontSize: 0,
    backgroundImage: `url(${imageUrl})`,
    backgroundSize
});

export const introLoaderAnimation = (
    positionX: string,
    positionY: string
): string => `
    @keyframes playX {
        0% {
            background-position-x: 0px;
        }
        100% {
            background-position-x: -${positionX};
        }
    }

    @keyframes playY {
        0% {
            background-position-y: 0px;
        }
        100% {
            background-position-y: -${positionY};
        }
    }

    .intro-loader {
        animation: playX 0.15s steps(10) infinite, playY 0.9s steps(6) infinite;
    }
`;
