import { Fragment } from 'react';
import { flow, pipe } from 'fp-ts/function';
import * as A from 'fp-ts/Array';
import * as E from 'fp-ts/Either';
import * as S from 'fp-ts/string';

const regex = /\B(#[\u0030-\uffff#]+)/gu;

export const StyledText = flow(
    S.replace(regex, '<hashtag>$&<hashtag>'),
    (str) => str.split('<hashtag>'),
    A.mapWithIndex((i, substring) =>
        pipe(
            substring,
            E.fromPredicate(
                (w) => regex.test(w),
                (substringLeft) => substringLeft
            ),
            E.match(
                (substringLeft) => <Fragment key={i}>{substringLeft}</Fragment>,
                (substringRight) => (
                    <span key={i} style={{ color: '#1DA1F2' }}>
                        {substringRight}
                    </span>
                )
            )
        )
    )
);
