import { useEffect, useState } from 'react';
import { useTheme } from '@mui/material/styles';
import { PostAnimationType, AnimationDuration } from '../../constants';
import { BackgroundCard } from '../../assets/styles/sns-card-styled-components';
import {
    animationStyles,
    animationStyleOpacity,
    getTimer$
} from '../../animations/animations';

import SnsCard from '../../components/sns-card';

import { SnsPost } from '../../types/sns-post';
import { SnsPostPageProps } from '../../types/sns-post-page';
import { secondsToMs } from '../../utils/time';
import { videoHandler } from '../../components/sns-video';
import { classesCss } from '../../assets/styles/sns-card-stylesheets';
import NoPosts from '../../components/no-posts';

// eslint-disable-next-line @typescript-eslint/prefer-readonly-parameter-types
const SnsPostPage = ({
    autoplaySpeed,
    animation,
    readyToPlay,
    snsPostResult,
    snsLogoResult,
    volume = 0,
    zeroPostsText,
    hasFullWidth,
    showThumbnail
}: SnsPostPageProps): JSX.Element => {
    const theme = useTheme();
    const { data, isFetching, isLoading, isLoadingError, isSuccess } =
        snsPostResult;
    const [hideImg, setHideImg] = useState<boolean>(false);

    const getOpacityStyle = (inTransition: boolean, disappear: boolean) => {
        if (animation.type !== PostAnimationType.opacity) {
            return {};
        }
        const staticStyle = {
            ...animationStyleOpacity.static,
            background: theme.palette.background.default
        };

        if (!inTransition) {
            return staticStyle;
        }

        const animationStyle = {
            animation: animationStyleOpacity[
                disappear ? 'disappear' : 'appear'
            ](animation.duration)
        };

        return { ...staticStyle, ...animationStyle };
    };

    const [currentState, setCurrentState] = useState({
        isInTransition: false,
        opacityStyle: getOpacityStyle(false, false),
        shownIndex: 0,
        currentPost: 0,
        ...animationStyles[animation.type],
        volume,
        isInitialPost: true,
        isPlaying: false,
        playInitialPost: true
    });

    const getStyle = (isPostShown: boolean, inTransition: boolean) => {
        const staticStyle = isPostShown
            ? currentState.shownPostStyle
            : currentState.hiddenPostStyle;
        if (!inTransition) {
            return staticStyle;
        }
        const animationStyle = {
            animation: isPostShown
                ? currentState.animationShownPost(animation.duration)
                : currentState.animationHiddenPost(animation.duration)
        };
        return { ...staticStyle, ...animationStyle };
    };

    const getPost = (n: number) => {
        const index =
            (currentState.currentPost +
                (currentState.shownIndex === n ? 0 : 1)) %
            (data as SnsPost[]).length;
        return (data as SnsPost[])[index];
    };

    const startTransition = () => {
        setCurrentState((prev) => ({
            ...prev,
            isInTransition: true,
            opacityStyle: getOpacityStyle(true, true)
        }));
    };

    const doFadeIn = () => {
        setCurrentState((prev) => ({
            ...prev,
            opacityStyle: getOpacityStyle(true, false)
        }));
    };

    const playVideo = () => {
        setHideImg(true);
        if (currentState.isInitialPost) {
            setCurrentState((prev) => ({ ...prev, isInitialPost: false }));
        } else if (animation.type === PostAnimationType.opacity) {
            doFadeIn();
            getTimer$(0.5 * AnimationDuration, videoHandler.play).subscribe();
            return;
        }
        videoHandler.play();
    };

    const playImage = () => {
        const playImageInterval = getTimer$(
            secondsToMs(autoplaySpeed),
            startTransition
        );
        if (currentState.isInitialPost) {
            setCurrentState((prev) => ({ ...prev, isInitialPost: false }));
        } else if (animation.type === PostAnimationType.opacity) {
            doFadeIn();
        }
        playImageInterval.subscribe();
    };

    const playElement = () => {
        const currentPost = (data as SnsPost[])[currentState.currentPost];
        if (currentPost.media.type === 'VIDEO') {
            videoHandler.load(
                currentPost.media.fileSrc,
                currentPost.id,
                animation.type === PostAnimationType.opacity &&
                    !currentState.isInitialPost,
                setCurrentState,
                getOpacityStyle,
                playVideo
            );
        } else {
            playImage();
        }
    };

    useEffect(() => {
        if (currentState.isInTransition) {
            getTimer$(animation.duration, () => {
                setCurrentState((prev) => ({
                    ...prev,
                    isInTransition: false,
                    isInitialPost: false,
                    shownIndex: 1 - prev.shownIndex,
                    currentPost:
                        (prev.currentPost + 1) % (data as SnsPost[]).length
                }));
            }).subscribe();
        } else if (currentState.isPlaying) {
            playElement();
        }
    }, [currentState.isInTransition, currentState.isPlaying]);

    useEffect(() => {
        if (
            isSuccess &&
            data &&
            currentState.currentPost === (data as SnsPost[]).length - 1
        ) {
            document.body.dispatchEvent(new Event('reload-sns-data'));
        }
    }, [isSuccess, data, currentState.currentPost]);

    useEffect(() => {
        let endFired = false;
        // eslint-disable-next-line functional/immutable-data
        videoHandler.onVideoEnded = () => {
            if (endFired) {
                return;
            }
            endFired = true;
            getTimer$(1000, () => {
                endFired = false;
            }).subscribe();
            setHideImg(false);
            videoHandler.cleanSrc(animation.type === PostAnimationType.opacity);
            startTransition();
        };
    }, []);

    useEffect(() => {
        const flagsReady = readyToPlay && isSuccess;
        const dataReady = Array.isArray(data) && data.length > 0;

        if (flagsReady && dataReady && !currentState.isPlaying) {
            setCurrentState((prev) => ({ ...prev, isPlaying: true }));
        }
    }, [isSuccess, readyToPlay, currentState.isPlaying]);

    if (snsPostResult.isSuccess && data?.length === 0) {
        return <NoPosts text={zeroPostsText} hasFullWidth={hasFullWidth} />;
    }

    return (
        <>
            <style>{classesCss(true)}</style>
            {(isFetching ||
                isLoading ||
                isLoadingError ||
                !data ||
                (data as SnsPost[]).length === 0) && (
                <SnsCard data={{ status: 'loading' }} />
            )}

            {data && (data as SnsPost[]).length > 1 && (
                <>
                    <BackgroundCard styleModification={{}}>
                        {[0, 1].map((n: number) => (
                            <SnsCard
                                key={`${getPost(n).id}`}
                                data={{
                                    status: 'success',
                                    snsPost: getPost(n),
                                    logo: snsLogoResult.data
                                }}
                                isInTransition={currentState.isInTransition}
                                styleModification={getStyle(
                                    currentState.shownIndex === n,
                                    animation.type === PostAnimationType.opacity
                                        ? false
                                        : currentState.isInTransition
                                )}
                                hasFullWidth={hasFullWidth}
                                hideImg={hideImg}
                                animation={animation}
                                showThumbnail={showThumbnail}
                            />
                        ))}
                    </BackgroundCard>
                    <BackgroundCard
                        styleModification={currentState.opacityStyle}
                    />
                </>
            )}
        </>
    );
};

export default SnsPostPage;
