import React, { ReactNode, useEffect, useState, useMemo } from 'react';
import { QueryObserverResult, UseQueryResult } from 'react-query';
import { identity } from 'fp-ts/function';
import { useSnsLogo, useSnsPosts } from '../hooks/queries';
import { SnsPost } from '../types/sns-post';
import equivalentPostsData from '../utils/equivalent-posts-data';
import {
    getPostsFromLocalStorage,
    storePostsInLocalStorage
} from '../utils/posts-from-local-storage';
import { cacheFiles } from '../utils/cache-files';
import { storeLogoInLocalStorage } from '../utils/logo-from-local-storage';

export const DataQueryProvider = ({
    children
}: {
    children: ReactNode;
}): JSX.Element => {
    const snsLogoResult: UseQueryResult<string> = useSnsLogo();
    const snsPostResult: UseQueryResult<SnsPost[]> = useSnsPosts(identity);

    const [afterInitialLoad, setAfterInitialLoad] = useState(false);

    const [previousPosts, setPreviousPosts] = useState<SnsPost[] | undefined>(
        getPostsFromLocalStorage
    );

    useEffect(() => {
        if (snsPostResult.isSuccess) {
            setAfterInitialLoad(true);
        }
    }, [snsPostResult.isSuccess]);

    const handleReloadData = (): Promise<
        QueryObserverResult<SnsPost[], unknown>
    > => snsPostResult.refetch();
    const handleReloadLogo = (): Promise<
        QueryObserverResult<string, unknown>
    > => snsLogoResult.refetch();

    useEffect(() => {
        if (snsLogoResult.isSuccess) {
            storeLogoInLocalStorage(snsLogoResult.data);
        }
    }, [snsLogoResult]);
    useEffect(() => {
        if (
            snsPostResult.data &&
            !equivalentPostsData(snsPostResult.data, previousPosts)
        ) {
            setPreviousPosts(snsPostResult.data);

            cacheFiles(snsPostResult.data).then((posts) => {
                storePostsInLocalStorage(posts);
            });
        }
    }, [snsPostResult]);

    useEffect(() => {
        document.body.addEventListener('reload-sns-data', handleReloadData);
        document.body.addEventListener('reload-sns-data', handleReloadLogo);
    }, []);

    const withData = useMemo(
        () =>
            React.Children.map(children, (child) => {
                if (React.isValidElement(child)) {
                    return React.cloneElement(child as React.ReactElement, {
                        snsLogoResult,
                        snsPostResult: {
                            ...snsPostResult,
                            data: previousPosts
                        },
                        dateTimestamp: Date.now()
                    });
                }

                return child;
            }),
        [previousPosts, snsLogoResult.isSuccess, afterInitialLoad]
    );

    return <>{withData}</>;
};
