import { useMemo } from 'react';
import {
    introLoaderAnimation,
    introLoaderStylesheet
} from '../assets/styles/sns-card-stylesheets';
import { SpinnerDimension } from '../types/intro-loader';
import LoadingSprite from '../assets/images/loading_sprite.png';

const IntroLoader = ({
    spinnerDimension
}: {
    spinnerDimension: SpinnerDimension;
}): JSX.Element => {
    const { value, unit } = spinnerDimension;
    const dimensions = useMemo(() => `${value}${unit}`, [spinnerDimension]);
    const positionX = useMemo(() => `${value * 10}${unit}`, [spinnerDimension]);
    const positionY = useMemo(() => `${value * 6}${unit}`, [spinnerDimension]);

    return (
        <>
            <style>{introLoaderAnimation(positionX, positionY)}</style>
            <div
                className="intro-loader"
                style={introLoaderStylesheet(
                    dimensions,
                    `${positionX} ${positionY}`,
                    LoadingSprite
                )}
            />
        </>
    );
};

export default IntroLoader;
