import * as FPTSString from 'fp-ts/string';
import { getEq } from 'fp-ts/Array';
import { SnsPost } from '../types/sns-post';

const ArrayStringEquality = getEq(FPTSString.Eq);

export default function equivalentPostsData(
    newData: SnsPost[] | undefined,
    previousData: SnsPost[] | undefined
): boolean {
    if (newData === undefined || previousData === undefined) {
        return false;
    }

    return ArrayStringEquality.equals(
        newData.map((x) => x.id),
        previousData.map((x) => x.id)
    );
}
