/**
 * @file Api data placed in Session Storage
 * @author Kostiantyn Burlai (k.burlai@samsung.com)
 * @date 2022-08-01
 * @description We decided to place the api data (baseUrl, logoUrl, authToken) in the sessionStorage
 *              on the application startup and every time data-config attribute is changing.
 *              This will ensure that every component will have access to this data and it's updates will not cause the app rerender.
 *              The structure of data-config is as follows: { api: {...}, <someOtherKeys>: {<someOtherObjectsWithConfig>} }
 *              Updating the api part of data-config object doesn't trigger the React app rerender.
 *              Changing everything else will trigger the React app rerender
 * @copyright Copyright (c) 2023 Samsung Electronics, Visual Display Division. All Rights Reserved.
 */

import { SessionStorageKeys } from '../constants';
import { Api } from '../types/api';

export const getApiFromSessionStorage = (): Api => ({
    baseUrl: sessionStorage.getItem(SessionStorageKeys.baseUrl)
        ? String(sessionStorage.getItem(SessionStorageKeys.baseUrl))
        : '',
    logoUrl: sessionStorage.getItem(SessionStorageKeys.logoUrl)
        ? String(sessionStorage.getItem(SessionStorageKeys.logoUrl))
        : '',
    authToken: sessionStorage.getItem(SessionStorageKeys.authToken)
        ? String(sessionStorage.getItem(SessionStorageKeys.authToken))
        : ''
});

export const setApiToSessionStorage = ({
    logoUrl,
    baseUrl,
    authToken
}: Api): void => {
    sessionStorage.setItem(SessionStorageKeys.logoUrl, logoUrl);
    sessionStorage.setItem(SessionStorageKeys.baseUrl, baseUrl);
    sessionStorage.setItem(SessionStorageKeys.authToken, authToken);
};
