import { useMemo } from 'react';
import { Avatar, Box } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { SnsPost } from '../../types/sns-post';
import { SnsPostsPageProps } from '../../types/sns-post-page';
import Images from '../../components/images';
import NoPosts from '../../components/no-posts';
import IntroLoader from '../../components/intro-loader';

const Logo = ({
    src,
    hasFullWidth
}: Readonly<{
    src: string;
    hasFullWidth: boolean;
}>): JSX.Element => {
    const iconDimension = hasFullWidth ? '6vw' : '12vh'; // 0.12*widget-height
    return (
        <Avatar
            sx={{
                position: 'absolute',
                bottom: '1.5em',
                right: '1.5em',
                width: iconDimension,
                height: iconDimension
            }}
            variant="square"
            alt="SNS"
            src={src}
        />
    );
};

const SnsPostsPage = ({
    snsLogoResult,
    snsPostResult,
    readyToPlay,
    scrollIntervalMs = 3000,
    zeroPostsText,
    hasFullWidth
}: Readonly<SnsPostsPageProps>): JSX.Element => {
    const theme = useTheme();
    const scroll = 2;
    const loadColumns = 5;
    const data = useMemo((): Array<SnsPost> => {
        if (!snsPostResult.isSuccess) {
            return [];
        }

        const result: Array<SnsPost> = (snsPostResult?.data || []).filter(
            (snsPost: SnsPost) => snsPost.thumbnailUrl !== undefined
        );

        const loadImages = loadColumns * 2;

        if (result.length > 0 && result.length < loadImages) {
            result.forEach((entry: SnsPost, index: number) => {
                const newEntry = {
                    ...entry,
                    id: `${entry.id}_${index}`
                } as SnsPost;
                // eslint-disable-next-line functional/immutable-data
                result.push(newEntry);
            });
        }

        return result;
    }, [snsPostResult.isSuccess, snsPostResult?.data]);

    if (snsPostResult.isSuccess && data?.length === 0) {
        return <NoPosts text={zeroPostsText} hasFullWidth={hasFullWidth} />;
    }

    return readyToPlay ? (
        <Box sx={{ backgroundColor: theme.palette.background.default }}>
            {data.length ? (
                <>
                    <Images
                        loadColumns={loadColumns}
                        scroll={scroll}
                        data={data}
                        scrollIntervalMs={scrollIntervalMs}
                    />
                    {snsLogoResult?.data && snsLogoResult?.isSuccess && (
                        <Logo
                            key={snsLogoResult.data}
                            src={snsLogoResult.data}
                            hasFullWidth={hasFullWidth}
                        />
                    )}
                </>
            ) : (
                <IntroLoader
                    spinnerDimension={
                        hasFullWidth
                            ? { value: 7, unit: 'vw' }
                            : { value: 14, unit: 'vh' }
                    }
                />
            )}
        </Box>
    ) : (
        <></>
    );
};

export default SnsPostsPage;
