import { SnsPost } from '../types/sns-post';
import logger from './logger';

const getFileSize = async (url: string): Promise<number> => {
    const response = await fetch(url, {
        method: 'HEAD'
    });

    const contentLength = response.headers.get('content-length');

    return contentLength ? parseInt(contentLength, 10) : 0;
};

const saveFileToSystem = async (url: string): Promise<string> => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    const destinationDirPath = `${window.assetsFolder}/sns`;

    const filename = url.substring(url.lastIndexOf('/') + 1).split('?')[0];

    const filesize = await getFileSize(url);

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    if (window.downloadFileIfNecessary === undefined) {
        logger.error('window.downloadFileIfNecessary is undefined');

        return url;
    }

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    await window.downloadFileIfNecessary({
        url,
        destinationDirPath,
        fileName: filename,
        header: null,
        verifyHost: false,
        file: {
            filesize,
            filename,
            filehash: filename
        }
    });

    // android player assetsFolder starts with 'file://', so we cant reuse item
    if (destinationDirPath.startsWith('file:')) {
        return `${destinationDirPath}/${filename}`;
    }

    return `file://${destinationDirPath}/${filename}`;
};

export const cacheFiles = async (
    items: readonly SnsPost[]
): Promise<SnsPost[]> => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    const isBrowser = window.cordova
        ? // eslint-disable-next-line @typescript-eslint/ban-ts-comment
          // @ts-ignore
          window.cordova.platformId === 'browser'
        : false;

    if (isBrowser || items.length === 0) {
        return Promise.resolve([...items]);
    }

    const updatedProfileImageSrc = await saveFileToSystem(
        items[0].user.profileImageSrc
    );

    const posts = await Promise.all(
        items.map(async (item) => {
            if (item.media.fileSrc.startsWith('file://')) return item;

            const updatedSrc = await saveFileToSystem(item.media.fileSrc);

            const updatedThumbnail =
                item.media.fileSrc !== item.thumbnailUrl &&
                item.thumbnailUrl !== undefined
                    ? await saveFileToSystem(item.thumbnailUrl)
                    : updatedSrc;

            return {
                ...item,
                media: {
                    ...item.media,
                    fileSrc: updatedSrc,
                    thumbnailUrl: updatedThumbnail
                },
                thumbnailUrl: updatedThumbnail,
                user: {
                    ...item.user,
                    profileImageSrc: updatedProfileImageSrc
                }
            };
        })
    );

    return posts;
};
