import { LoggerObject, LoggerType, LoggerMode } from '../types/logger';

const consoleLogger: LoggerObject = {
    log: (msg: any) => console.log(msg),
    warn: (msg: any) => console.warn(msg),
    error: (msg: any) => console.error(msg)
};

const wineApiLogger: LoggerObject = {
    log: (msg: any) => {
        /* TODO */
        console.log(`TODO: Send log request to wineApi with msg = ${msg}`);
    },
    warn: (msg: any) => {
        /* TODO */
        console.log(`TODO: Send warn log request to wineApi with msg = ${msg}`);
    },
    error: (msg: any) => {
        /* TODO */
        console.log(
            `TODO: Send error log request to wineApi with msg = ${msg}`
        );
    }
};

const emptyLogger: LoggerObject = {
    log: () => {},
    warn: () => {},
    error: () => {}
};

class Logger {
    logger: LoggerObject;

    mode: LoggerMode;

    LABEL = 'SNS-WIDGET';

    constructor() {
        this.logger = consoleLogger;
        this.mode = process.env.NODE_ENV === 'development' ? 'DEV' : 'PROD';
    }

    setLogger(type: LoggerType) {
        switch (type) {
            case 'CONSOLE':
                this.logger = consoleLogger;
                break;
            case 'WINEAPI':
                this.logger = wineApiLogger;
                break;
            default:
                this.logger = emptyLogger;
        }
    }

    private header() {
        const timestamp = new Date()
            .toISOString()
            .replace('T', ' ')
            .replace(/[.].*/, '');
        return `[${this.LABEL} ${timestamp}]: `;
    }

    log(msg: any) {
        if (this.mode === 'DEV') {
            this.logger.log(`${this.header()}${msg}`);
        }
    }

    warn(msg: any) {
        this.logger.warn(`${this.header()}${msg}`);
    }

    error(msg: any) {
        this.logger.error(`${this.header()}${msg}`);
    }
}

export default new Logger();
