import { useQuery, UseQueryResult } from 'react-query';
import { getApiFromSessionStorage } from '../services/api-session-storage';
import { Api } from '../types/api';
import { ApiError } from '../types/api-error';
import { isSnsPost, SnsPost } from '../types/sns-post';
import { queue2 } from '../utils/queue-2';
import { minutesToMs } from '../utils/time';
import Logger from '../utils/logger';
import { arrayBufferToBase64 } from '../utils/base64';
import { getPostsFromLocalStorage } from '../utils/posts-from-local-storage';
import { getLogoFromLocalStorage } from '../utils/logo-from-local-storage';

const isCarouselAlbum = (value: any): boolean =>
    value.mediaType === 'CAROUSEL_ALBUM' && Array.isArray(value.children?.data);

const wrapWithToken = (href: string, token: string) => {
    if (
        !href ||
        !/content.samsungvx.com$/gi.test(new URL(href).host) ||
        !token
    ) {
        return href;
    }

    const operator = href.split('?').length > 1 ? '&' : '?';
    return `${href}${operator}token=${token}`;
};

const parseResponseData = (data: any, authToken: string): SnsPost[] => {
    const res = data.data
        .map((value: any) => ({
            id: value.id,
            created: value.timestamp,
            hashtag: data.hashtag ? `#${data.hashtag}` : '',
            likeCount: value.likeCount,
            text: value.caption,
            thumbnailUrl: wrapWithToken(
                value.thumbnailUrl ||
                    (isCarouselAlbum(value)
                        ? value.children.data[0]?.mediaUrl
                        : value.mediaUrl),
                authToken
            ),
            // TODO support all children of CAROUSEL_ALBUM
            media: isCarouselAlbum(value)
                ? {
                      type: value.children.data[0]?.mediaType,
                      fileSrc: wrapWithToken(
                          value.children.data[0]?.mediaUrl,
                          authToken
                      )
                  }
                : {
                      type: value.mediaType,
                      fileSrc: wrapWithToken(value.mediaUrl, authToken)
                  },
            sns: { type: '', logoSrc: '' },
            user: {
                name: data.businessDiscovery?.name || '',
                profileImageSrc: wrapWithToken(
                    data.businessDiscovery?.profilePictureUrl || '',
                    authToken
                )
            }
        }))
        .filter(isSnsPost);

    if (res.length) {
        return res.length > 1 ? res : ([res[0], res[0]] as SnsPost[]);
    }

    return res as SnsPost[];
};

const getErrorMsg = (response: any): string =>
    response?.error?.message || response?.message || 'Unknown error';

const fetchSns = ({
    baseUrl,
    authToken
}: Readonly<Api>): Promise<SnsPost[]> => {
    if (baseUrl === '') {
        return Promise.resolve([]);
    }
    return fetch(baseUrl, {
        headers: {
            'Content-Type': 'application/json',
            Accept: 'application/json',
            ...(authToken.trim() === '' ? {} : { Authorization: authToken })
        },
        credentials: 'include'
    })
        .then((response) =>
            response.ok
                ? response.json()
                : response.json().then((res) => {
                      Logger.error(`Fetch media error: ${JSON.stringify(res)}`);
                      return Promise.reject(new ApiError(getErrorMsg(res)));
                  })
        )
        .then((data) => parseResponseData(data, authToken));
};

const fetchLogo = ({ logoUrl, authToken }: Readonly<Api>): Promise<string> =>
    fetch(logoUrl, {
        headers: {
            Accept: 'image/*',
            ...(authToken.trim() === '' ? {} : { Authorization: authToken })
        },
        credentials: 'include'
    })
        .then((response) =>
            response.ok
                ? response.arrayBuffer()
                : response.json().then((res) => {
                      Logger.error(`Fetch logo error: ${JSON.stringify(res)}`);
                      return Promise.reject(new ApiError(getErrorMsg(res)));
                  })
        )
        .then((resp) => arrayBufferToBase64(resp));

export const useSnsPosts = (
    select: (data: SnsPost[]) => unknown
): UseQueryResult<SnsPost[]> => {
    const apiConfig = getApiFromSessionStorage();

    return apiConfig.baseUrl === undefined
        ? (useQuery(['sns-posts', apiConfig.baseUrl], () =>
              Promise.resolve([])
          ) as UseQueryResult<SnsPost[]>)
        : (useQuery(
              ['sns-posts', apiConfig.baseUrl],
              fetchSns.bind(null, apiConfig),
              {
                  refetchInterval: minutesToMs(5),
                  initialData: () => {
                      if (!window.navigator.onLine) {
                          return getPostsFromLocalStorage();
                      }

                      // Here and in similar cases we intentionally returning undefined because that's how react-query works for such scenarios:
                      // https://tanstack.com/query/v3/docs/react/guides/initial-query-data#conditional-initial-data-from-cache
                      return undefined;
                  },
                  select
              }
          ) as UseQueryResult<SnsPost[]>);
};

export const useSnsPostsQueue2 = (
    headId: string | undefined
): UseQueryResult<[SnsPost, SnsPost]> =>
    useSnsPosts(queue2(({ id }) => id === headId)) as UseQueryResult<
        [SnsPost, SnsPost],
        unknown
    >;

export const useSnsLogo = (): UseQueryResult<string> => {
    const apiConfig = getApiFromSessionStorage();
    return apiConfig.logoUrl === undefined
        ? useQuery(['sns-logo'], () => Promise.resolve(''))
        : useQuery(
              ['sns-logo', apiConfig.logoUrl],
              fetchLogo.bind(null, apiConfig),
              {
                  initialData: () => {
                      if (!window.navigator.onLine) {
                          return getLogoFromLocalStorage();
                      }

                      return undefined;
                  }
              }
          );
};
