export enum Ready {
    // No information is available about the media resource.
    HAVE_NOTHING = 0,

    /* Enough of the media resource has been retrieved that the metadata 
    attributes are initialized. Seeking will no longer raise an exception. */
    HAVE_METADATA = 1,

    /* Data is available for the current playback position, 
    but not enough to actually play more than one frame. */
    HAVE_CURRENT_DATA = 2,

    /* Data for the current playback position as well as for at 
    least a little bit of time into the future is available 
    (in other words, at least two frames of video, for example). */
    HAVE_FUTURE_DATA = 3,

    /* Enough data is available—and the download rate is high 
    enough—that the media can be played through to the end without interruption. */
    HAVE_ENOUGH_DATA = 4
}
export type ReadyStateValue = 0 | 1 | 2 | 3 | 4;

export enum Network {
    // There is no data yet. Also, readyState is HAVE_NOTHING.
    NETWORK_EMPTY = 0,

    /* Data source is active and has selected a resource, 
    but is not using the network */
    NETWORK_IDLE = 1,

    // The data is being downloaded.
    NETWORK_LOADING = 2,

    // No data source found.
    NETWORK_NO_SOURCE = 3
}
export type NetworkStateValue = 0 | 1 | 2 | 3;

export class WidgetState {
    private readyState: Ready;

    public getReadyState(): string {
        return Ready[this.readyState];
    }

    public getReadyStateValue(): number {
        return this.readyState;
    }

    // eslint-disable-next-line functional/no-return-void
    public setReadyState(newReadyState: ReadyStateValue): void {
        this.readyState = newReadyState;
    }

    private networkState: Network;

    public getNetworkState(): string {
        return Network[this.networkState];
    }

    public getNetworkStateValue(): number {
        return this.networkState;
    }

    // eslint-disable-next-line functional/no-return-void
    public setNetworkState(newNetworkState: NetworkStateValue): void {
        this.networkState = newNetworkState;
    }

    constructor(
        initialReadyState: Ready = Ready.HAVE_NOTHING,
        initialNetworkState: Network = Network.NETWORK_EMPTY
    ) {
        this.readyState = initialReadyState;
        this.networkState = initialNetworkState;
    }
}
