import { CardMedia } from '@mui/material';
import { useRef, useEffect, useState } from 'react';
import { getTimer$ } from '../animations/animations';
import { AnimationDuration } from '../constants';
import { SnsVideoProps } from '../types/sns-video';
import { VideoContentBox } from '../assets/styles/sns-card-styled-components';

const videoHandler: {
    play: () => void;
    load: (
        src: string,
        postId: string,
        doOpacityAnimation: boolean,
        setPostState: React.Dispatch<React.SetStateAction<any>>,
        getOpacityStyle: (inTransition: boolean, disappear: boolean) => any,
        playVideo: () => void
    ) => void;
    cleanSrc: (isOpacityAnimaiton: boolean) => void;
    onVideoEnded: () => void;
} = {
    play: () => {},
    load: () => {},
    cleanSrc: () => {},
    onVideoEnded: () => {}
};

const getVideoStyle = (hasFullWidth: boolean) => ({
    margin: hasFullWidth ? '3vw auto' : '6vh auto',
    height: hasFullWidth ? '44vw' : '88vh',
    width: 'auto',
    maxWidth: '95%'
});

const SnsVideo = ({ hasFullWidth }: SnsVideoProps): JSX.Element => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const [onCanPlayThroughFunc, setOnCanPlayThroughFunc] = useState<{
        onCanPlayTF: React.ReactEventHandler<HTMLVideoElement> | undefined;
    }>({ onCanPlayTF: undefined });

    const [videoState, setVideoState] = useState({
        canPlay: false,
        src: '',
        postId: '',
        showVideo: false
    });

    useEffect(() => {
        // eslint-disable-next-line functional/immutable-data
        videoHandler.play = () => {
            setVideoState((prev) => ({ ...prev, showVideo: true }));
        };

        // eslint-disable-next-line functional/immutable-data
        videoHandler.load = (
            src,
            postId,
            doOpacityAnimation,
            setPostState,
            getOpacityStyle,
            playVideo
        ) => {
            setVideoState((prev) => ({ ...prev, src, postId }));
            const newCanPlayThroughFunc = () => {
                if (!videoState.canPlay) {
                    if (doOpacityAnimation) {
                        setPostState((prev: any) => ({
                            ...prev,
                            opacityStyle: getOpacityStyle(true, false)
                        }));
                    }
                    playVideo();
                    setVideoState((prev) => ({ ...prev, canPlay: true }));
                }
            };
            setOnCanPlayThroughFunc({ onCanPlayTF: newCanPlayThroughFunc });
        };

        // eslint-disable-next-line functional/immutable-data
        videoHandler.cleanSrc = (isOpacityAnimaiton: boolean) => {
            const doCleanSrc = () => {
                const videoSrc = videoRef?.current?.src || '';
                if (videoSrc === '') {
                    return;
                }
                setVideoState((prev) => ({
                    ...prev,
                    showVideo: false,
                    canPlay: false,
                    src: ''
                }));
                videoRef?.current?.removeAttribute('src');
                videoRef?.current?.load();
            };
            if (videoRef.current) {
                if (isOpacityAnimaiton) {
                    getTimer$(AnimationDuration, doCleanSrc).subscribe();
                } else {
                    doCleanSrc();
                }
            }
        };
    }, []);

    useEffect(() => {
        if (videoRef.current && videoState.canPlay && videoState.showVideo) {
            videoRef?.current?.play();
        }
    }, [videoState.canPlay, videoState.showVideo]);

    return (
        <VideoContentBox>
            <CardMedia
                key={`video_${videoState.postId}`}
                ref={videoRef}
                onCanPlayThrough={(event) => {
                    onCanPlayThroughFunc.onCanPlayTF?.(event);
                }}
                sx={{
                    ...getVideoStyle(hasFullWidth),
                    opacity: videoState.showVideo ? 1 : 0
                }}
                aria-label="video"
                component="video"
                muted
                poster="data:image/gif;base64,R0lGODlhAQABAIAAAP///wAAACH5BAEAAAAALAAAAAABAAEAAAICRAEAOw=="
                preload="auto"
                src={videoState.src}
                // eslint-disable-next-line functional/prefer-tacit
                onEnded={() => videoHandler.onVideoEnded()}
            />
        </VideoContentBox>
    );
};

// eslint-disable-next-line functional/immutable-data
SnsVideo.displayName = 'SnsVideo';

export { videoHandler };

export default SnsVideo;
