import Bicycle from './bicycle';

type BicycleLoaderType = {
    readonly active?: boolean;
    readonly hasFullWidth: boolean;
};

const BicycleLoader = ({
    active,
    hasFullWidth
}: BicycleLoaderType): JSX.Element => {
    const bicycleLoaderDimension = hasFullWidth ? '43.75vw' : '87.5vh'; // 0.875*widget-height

    return (
        <div
            key="bicycle_wrapper"
            className="bicycle_loader"
            style={{
                height: bicycleLoaderDimension,
                width: bicycleLoaderDimension,
                position: 'absolute',
                top: '1vw',
                left: '2vw',
                bottom: '1vw',
                right: '0',
                margin: 'auto',
                zIndex: '4000',
                backgroundColor: '#9C9C9C',
                overflow: 'hidden',
                visibility: active ? 'visible' : 'hidden',
                display: active ? 'flex' : 'none',
                alignItems: 'center',
                justifyContent: 'center'
            }}
            // TODO p.kubala find the way to get rid of test-id
            data-testid="bicycleLoader"
        >
            <Bicycle key="bicycle_animated_svg" />
        </div>
    );
};

export default BicycleLoader;
