import { flow } from 'fp-ts/function';

export const secondsToMs = (s: number): number => s * 1000;

export const minutesToMs = flow((m: number) => m * 60, secondsToMs);

export const hoursToMs = flow((h: number) => h * 60, minutesToMs);
