export const initialWidgetErrorState: WidgetErrorState = {
    errorDetected: false
};

export type WidgetErrorState =
    | { errorDetected: false }
    | {
          errorDetected: true;
          errorMessage: string;
      };

export const initialSnsError: SnsError = {
    errorState: initialWidgetErrorState,
    updateErrorState: (newErrorState: WidgetErrorState) => {
        console.log(newErrorState);
    }
};

export interface SnsError {
    errorState: WidgetErrorState;
    updateErrorState: (newErrorState: WidgetErrorState) => void;
}
