import { styled } from '@mui/material/styles';
import { Box, CardContent, Card, Typography } from '@mui/material';
import {
    backgroundCardStylesheet,
    bottomContentBoxStyleSheet,
    captionTypographyStylesheet,
    containerBoxStylesheet,
    contentBoxStylesheet,
    descriptionTypographyStylesheet,
    likeCounterTypographyStylesheet,
    mainBoxStylesheet,
    noPostsTypographyStylesheet,
    snsCardContentStylesheet,
    squareContainerDivBoxStylesheet,
    titleTypographyStylesheet,
    topContentBoxStylesheet,
    videoContentBoxStylesheet
} from './sns-card-stylesheets';

export const SnsCardContent = styled(CardContent)(snsCardContentStylesheet);

export const TopContentBox = styled(Box)(topContentBoxStylesheet);

export const BottomContentBox = styled(Box)(bottomContentBoxStyleSheet);

export const MainBox = styled(Box)(mainBoxStylesheet);

const shouldForwardPropBgCard = {
    shouldForwardProp: (prop: string) =>
        prop !== 'sx' && prop !== 'styleModification'
};

export const BackgroundCard = styled(
    Card,
    shouldForwardPropBgCard
)(backgroundCardStylesheet);

const shouldForwardPropObj = {
    shouldForwardProp: (prop: string) =>
        prop !== 'sx' && prop !== 'hasFullWidth'
};

export const ContentBox = styled(
    Box,
    shouldForwardPropObj
)(contentBoxStylesheet);

export const TitleTypography = styled(
    Typography,
    shouldForwardPropObj
)(titleTypographyStylesheet);

export const CaptionTypography = styled(
    Typography,
    shouldForwardPropObj
)(captionTypographyStylesheet);

export const DescriptionTypography = styled(
    Typography,
    shouldForwardPropObj
)(descriptionTypographyStylesheet);

export const NoPostsTypography = styled(
    Typography,
    shouldForwardPropObj
)(noPostsTypographyStylesheet);

export const LikeCounterTypography = styled(
    Typography,
    shouldForwardPropObj
)(likeCounterTypographyStylesheet);

export const SquareContainerDivBox = styled(Box)<{
    component: string;
}>(squareContainerDivBoxStylesheet);

const shouldForwardPropContBox = {
    shouldForwardProp: (prop: string) =>
        prop !== 'sx' && prop !== 'styleModification' && prop !== 'data'
};

export const ContainerBox = styled(
    Box,
    shouldForwardPropContBox
)(containerBoxStylesheet);

export const VideoContentBox = styled(Box)(videoContentBoxStylesheet);
