import { Avatar, CardHeader, Typography } from '@mui/material';

type DefaultHeaderParams = Readonly<{
    logo: string;
    hasFullWidth: boolean;
    headerText: string;
}>;

const DefaultHeader = ({
    logo,
    hasFullWidth,
    headerText
}: DefaultHeaderParams): JSX.Element => (
    <CardHeader
        sx={{ height: '10%', paddingBottom: '1%' }}
        avatar={
            <Avatar
                src={logo}
                alt="SNS"
                variant="square"
                sx={{
                    height: hasFullWidth ? '5.5vw' : '11vh', // 0.11*widget-height
                    width: hasFullWidth ? '5.5vw' : '11vh' // 0.11*widget-height
                }}
            />
        }
        title={
            <Typography
                sx={{
                    fontWeight: 600,
                    fontSize: hasFullWidth ? '3.5vw' : '7vh' // 0.07*widget-height
                }}
            >
                {headerText}
            </Typography>
        }
    />
);

export default DefaultHeader;
