// eslint-disable-next-line import/no-extraneous-dependencies
import { isEqual } from 'lodash-es';
import { StrictMode } from 'react';
import * as ReactDOM from 'react-dom';
import { pipe } from 'fp-ts/function';
import { fold } from 'fp-ts/lib/Either';

import { App } from './app';
import { DataQueryProvider } from './context/data-query-provider';
import { ContainerQueriesBreakpointProvider } from './context/container-queries-breakpoint';
import { MuiProvider } from './context/mui-provider';
import { QueryProvider } from './context/query-provider';
import { AppProps } from './types/app';
import { WidgetConfig } from './types/widget-config';
import { parseWidgetConfigAttribute } from './utils/parse-widget-config-attribute';
import { SupernovaWidget } from '../widget-interface/supernova-widget';
import Logger from './utils/logger';
import { setApiToSessionStorage } from './services/api-session-storage';
import {
    AnimationDuration,
    DATA_CONFIG_KEY,
    PostAnimationType
} from './constants';
import { ErrorProvider } from './context/error';

const css = `
    :host {
        display: block;
        contain: content;
        height: 100%;
    }

    :host > div,
    :host > div > div {
        height: inherit;
    }

    .no-scrollbar > div > div {
        width: 50vh;
        height: 100%;
    }
`;

export class SupernovaSns extends SupernovaWidget {
    private parsedConfig: WidgetConfig;

    private readonly fallbackConfig: WidgetConfig;

    constructor() {
        super();

        this.fallbackConfig = {
            api: { baseUrl: '', logoUrl: '', authToken: '' },
            displayMode: 'SPLASH_SCREEN',
            animation: { type: PostAnimationType.none, duration: 0 },
            autoplay: false,
            autoplaySpeed: 10,
            volume: 0,
            showThumbnail: true
        };

        this.parsedConfig = this.fallbackConfig;

        this.setDefaults();
        this.emotionRoot.appendChild(document.createTextNode(css));
    }

    // eslint-disable-next-line functional/no-return-void
    private setDefaults(): void {
        this.readyToPlay = null;
    }

    static observedAttributes = [DATA_CONFIG_KEY];

    // eslint-disable-next-line functional/no-return-void
    protected reportReady(): void {
        this.onReady();
        this.readyWasReported = true;
    }

    // eslint-disable-next-line functional/no-return-void
    play(): void {
        this.readyToPlay = true;
        this.render(this.parsedConfig);
    }

    // eslint-disable-next-line functional/no-return-void
    pause(): void {
        this.readyToPlay = false;
        this.render(this.parsedConfig);
    }

    // eslint-disable-next-line functional/no-return-void
    mute(): void {
        const config = { ...this.parsedConfig, volume: 0 };
        this.render(config);
    }

    // eslint-disable-next-line functional/no-return-void
    unmute(): void {
        const config = { ...this.parsedConfig, volume: 100 };
        this.render(config);
    }

    /* eslint-disable-next-line functional/no-return-void */
    protected initialize(): void {
        this.readyToPlay = null;
        const shadowRoot = this.attachShadow({ mode: 'closed' });
        shadowRoot.appendChild(this.emotionRoot);
        shadowRoot.appendChild(this.mountPoint);
    }

    /* eslint-disable-next-line functional/no-return-void */
    protected render(widgetConfig: WidgetConfig): void {
        const { containerBreakpoints, ...themeOptions } =
            widgetConfig.theme || {};
        const animation = widgetConfig.animation || {
            type: PostAnimationType.opacity,
            duration: AnimationDuration
        };
        const showThumbnail = animation.type !== PostAnimationType.opacity;

        const appProps = {
            readyToPlay: this.readyToPlay,
            config: { ...widgetConfig, animation, showThumbnail }
        } as AppProps;

        ReactDOM.unmountComponentAtNode(this.mountPoint);
        if (!this.readyToPlay) {
            return;
        }
        // TODO p.kubala switch to createRoot
        ReactDOM.render(
            <StrictMode>
                <MuiProvider
                    emotionRoot={this.emotionRoot}
                    themeOptions={themeOptions}
                >
                    <ContainerQueriesBreakpointProvider
                        value={containerBreakpoints?.values?.sm || 600}
                    >
                        <ErrorProvider>
                            <QueryProvider>
                                <DataQueryProvider>
                                    {/* eslint-disable-next-line react/jsx-props-no-spreading */}
                                    <App {...appProps} />
                                </DataQueryProvider>
                            </QueryProvider>
                        </ErrorProvider>
                    </ContainerQueriesBreakpointProvider>
                </MuiProvider>
            </StrictMode>,
            this.mountPoint
        );
    }

    protected attributeChangedCallback(
        name: string,
        _oldValue: string,
        newValue: string
        /* eslint-disable-next-line functional/no-return-void */
    ): void {
        const previousObject = JSON.parse(_oldValue);
        const newObject = JSON.parse(newValue);

        const previousApiObject = previousObject?.api;
        const newApiObject =
            this.parsedConfig.canvasConfig?.content.keyword === ''
                ? { ...newObject?.api, baseUrl: '' }
                : newObject?.api;

        delete previousObject?.api;
        delete newObject?.api;

        switch (name) {
            case `${DATA_CONFIG_KEY}`:
                if (!isEqual(previousApiObject, newApiObject)) {
                    setApiToSessionStorage({
                        logoUrl: newApiObject?.logoUrl,
                        baseUrl: newApiObject?.baseUrl,
                        authToken: newApiObject?.authToken
                    });
                }
                if (!isEqual(previousObject, newObject)) {
                    this.renderWithConfig(newValue, 'attributeChangedCallback');
                }
                break;
            default:
                Logger.warn(`no attribute ${name} found!`);
        }
    }

    /* eslint-disable-next-line functional/no-return-void */
    protected renderWithConfig(config: string, callerName: string): void {
        pipe(
            config,
            parseWidgetConfigAttribute,
            fold(
                (err: unknown) => {
                    Logger.error(`${callerName} render failed: ${err}`);
                    this.render(this.fallbackConfig);
                },
                (widgetConfig: WidgetConfig) => {
                    this.parsedConfig = widgetConfig;

                    if ('autoplay' in this.parsedConfig) {
                        this.readyToPlay = !!this.parsedConfig.autoplay;
                    } else {
                        this.readyToPlay = !!this.fallbackConfig.autoplay;
                    }

                    this.render(this.parsedConfig);
                }
            )
        );
    }

    /* eslint-disable-next-line functional/no-return-void */
    protected connectedCallback(): void {
        this.initialize();

        const apiConfig = this.getAttribute(DATA_CONFIG_KEY)
            ? JSON.parse(String(this.getAttribute(DATA_CONFIG_KEY)))?.api
            : this.fallbackConfig.api;
        setApiToSessionStorage(apiConfig);

        const config =
            this.getAttribute(DATA_CONFIG_KEY) ||
            JSON.stringify(this.fallbackConfig);
        this.renderWithConfig(config, 'connectedCallback');
    }

    /* eslint-disable-next-line functional/no-return-void */
    protected disconnectedCallback(): void {
        ReactDOM.unmountComponentAtNode(this.mountPoint);
    }
}
