import { useEffect, useState } from 'react';

const BicycleStyle = `
.cls-1 {
    isolation: isolate;
}

.cls-2 {
    fill: #9c9c9c;
    opacity: 0;
}

.cls-3 {
    fill: #7e7e7e;
    mix-blend-mode: multiply;
    opacity: 0.2;
}

.cls-4, .cls-5, .cls-6 {
    fill: none;
}

.cls-4, .cls-6 {
    stroke: #222;
}

.cls-4, .cls-5 {
    stroke-linecap: round;
}

.cls-4 {
    stroke-linejoin: round;
    stroke-width: 9.647px;
}

.cls-5 {
    stroke: #b5b5b5;
    stroke-width: 8.575px;
}

.cls-5, .cls-6 {
    stroke-miterlimit: 10;
}

.cls-6 {
    stroke-width: 6.431px;
}

.cls-7 {
    fill: #f1f1f1;
}
`;

const states = [
    [
        { x: '416.523', y: '299.342' },
        { x: '361.472', y: '299.342' }
    ],
    [
        { x: '414.863', y: '289.927' },
        { x: '363.132', y: '308.756' }
    ],
    [
        { x: '410.084', y: '281.648' },
        { x: '367.912', y: '317.035' }
    ],
    [
        { x: '402.761', y: '275.504' },
        { x: '375.235', y: '323.179' }
    ],
    [
        { x: '393.778', y: '272.234' },
        { x: '384.218', y: '326.449' }
    ],
    [
        { x: '384.222', y: '272.03' },
        { x: '393.782', y: '326.245' }
    ],
    [
        { x: '375.169', y: '275.311' },
        { x: '402.694', y: '322.986' }
    ],
    [
        { x: '367.784', y: '281.49' },
        { x: '409.955', y: '316.876' }
    ],
    [
        { x: '362.958', y: '289.822' },
        { x: '414.689', y: '308.65' }
    ]
];

const Bicycle = (): JSX.Element => {
    const [state, setState] = useState<number>(0);
    const coords = states[state];
    const key1 = `${coords[0].x}_${coords[0].y}`;
    const key2 = `${coords[1].x}_${coords[1].y}`;

    useEffect(() => {
        const tOut = setTimeout(() => {
            let nextState = state + 1;

            if (!states[nextState]) {
                nextState = 0;
            }

            setState(nextState);
        }, 100);

        return () => clearTimeout(tOut);
    }, [state]);

    return (
        <svg viewBox="0 0 776 436" key="svg_main" style={{ height: '100vh' }}>
            <defs key="defs">
                <style key="style">{BicycleStyle}</style>
            </defs>
            <g className="cls-1" key="g_main">
                <rect key="rect" className="cls-2" width="776" height="436" />
                <g key="g_secondary">
                    <ellipse
                        key="ellipse"
                        className="cls-3"
                        cx="388"
                        cy="341.11"
                        rx="170.852"
                        ry="11.487"
                    />
                    <circle
                        key="circle_1"
                        className="cls-4"
                        cx="285.031"
                        cy="285.042"
                        r="48.96"
                    />
                    <path
                        key="path_1"
                        className="cls-5"
                        d="M289.61,255.09a30.3,30.3,0,0,0-13.588,58.885"
                    />
                    <circle
                        key="circle_2"
                        className="cls-6"
                        cx="388.998"
                        cy="299.342"
                        r="16.527"
                    />
                    <g key="g_animated">
                        <circle
                            key={key1}
                            className="cls-7"
                            cx={coords[0].x}
                            cy={coords[0].y}
                            r="4.544"
                        />
                        <circle
                            key={key2}
                            className="cls-7"
                            cx={coords[1].x}
                            cy={coords[1].y}
                            r="4.544"
                        />
                    </g>
                    <circle
                        key="circle_3"
                        className="cls-4"
                        cx="490.969"
                        cy="285.042"
                        r="48.96"
                    />
                    <path
                        key="path_2"
                        className="cls-5"
                        d="M495.548,255.09a30.3,30.3,0,0,0-13.588,58.885"
                    />
                    <polyline
                        key="polyline"
                        className="cls-4"
                        points="312.548 243.562 386.568 153.681 351.206 153.681"
                    />
                    <line
                        key="line_1"
                        className="cls-4"
                        x1="366.561"
                        y1="179.187"
                        x2="444.489"
                        y2="265.186"
                    />
                    <line
                        key="line_2"
                        className="cls-4"
                        x1="468.37"
                        y1="204.993"
                        x2="432.608"
                        y2="204.993"
                    />
                    <line
                        key="line_3"
                        className="cls-4"
                        x1="452.212"
                        y1="206.107"
                        x2="424.632"
                        y2="239.077"
                    />
                </g>
            </g>
        </svg>
    );
};

export default Bicycle;
