import { useMemo, useState, useContext } from 'react';

import { AppProps } from './types/app';
import { DisplayMode, isDisplayMode } from './types/display-mode';
import { secondsToMs } from './utils/time';

import Intro from './pages/intro/intro';
import SnsPostPage from './pages/sns-post-page/sns-post-page';
import SnsPostsPage from './pages/sns-posts-page/sns-posts-page';
import SnsVideo from './components/sns-video';
import { ErrorContext } from './context/error';
import ErrorPage from './pages/error-page/error-page';

// eslint-disable-next-line functional/no-return-void
const setProperBodySizes =
    (setHasFullWidth: React.Dispatch<React.SetStateAction<boolean>>) =>
    (): void => {
        const trueWidth = window.innerWidth;
        const trueHeight = window.innerHeight;

        let width = 0;
        let height = 0;
        let toLeft = 0;
        let toTop = 0;

        if (trueWidth / 2 > trueHeight) {
            width = trueHeight * 2;
            height = trueHeight;
            toLeft = (trueWidth - width) / 2;
            setHasFullWidth(false);
        } else {
            width = trueWidth;
            height = trueWidth / 2;
            toTop = (trueHeight - height) / 2;
            setHasFullWidth(true);
        }

        document.body.style.setProperty('width', `${width}px`);
        document.body.style.setProperty('height', `${height}px`);
        document.body.style.setProperty('margin-top', `${toTop}px`);
        document.body.style.setProperty('margin-left', `${toLeft}px`);
    };

export const App = ({
    config: {
        autoplaySpeed = 10,
        displayMode = 'SPLASH_SCREEN',
        intro = "Create your own Instagram Wall for your digital screen. Promote your business with your latest posts.\n\nLet's begin with your Facebook log-in.",
        name = 'Instagram Business',
        animation,
        volume = 0,
        zeroPostsText = 'No Posts',
        canvasConfig = { content: { keyword: '' } },
        showThumbnail = true
    },
    snsLogoResult,
    snsPostResult,
    readyToPlay,
    dateTimestamp = Date.now()
}: AppProps): JSX.Element => {
    const ms = useMemo(() => secondsToMs(autoplaySpeed), [autoplaySpeed]);
    const [hasFullWidth, setHasFullWidth] = useState<boolean>(false);

    const { errorState } = useContext(ErrorContext);

    setTimeout(setProperBodySizes(setHasFullWidth), 100);
    window.addEventListener('resize', setProperBodySizes(setHasFullWidth));

    if (canvasConfig.content.keyword === '') {
        return (
            <Intro
                intro={intro}
                logo={snsLogoResult.data || ''}
                name={name}
                hasFullWidth={hasFullWidth}
            />
        );
    }

    const renderElement = (): JSX.Element => {
        if (isDisplayMode(displayMode)) {
            switch (displayMode as DisplayMode) {
                case 'SINGLE':
                    return (
                        <>
                            <SnsVideo hasFullWidth={hasFullWidth} />
                            <SnsPostPage
                                animation={animation}
                                autoplaySpeed={autoplaySpeed}
                                readyToPlay={readyToPlay}
                                snsLogoResult={snsLogoResult}
                                snsPostResult={snsPostResult}
                                volume={volume}
                                key={dateTimestamp.toString()}
                                zeroPostsText={zeroPostsText}
                                hasFullWidth={hasFullWidth}
                                showThumbnail={showThumbnail}
                            />
                        </>
                    );
                case 'MULTI':
                    return (
                        <SnsPostsPage
                            scrollIntervalMs={ms}
                            snsLogoResult={snsLogoResult}
                            snsPostResult={snsPostResult}
                            readyToPlay={readyToPlay}
                            key={dateTimestamp.toString()}
                            zeroPostsText={zeroPostsText}
                            hasFullWidth={hasFullWidth}
                        />
                    );
                default:
                    return (
                        <Intro
                            intro={intro}
                            logo={snsLogoResult.data || ''}
                            name={name}
                            hasFullWidth={hasFullWidth}
                        />
                    );
            }
        } else {
            return <></>;
        }
    };

    return errorState.errorDetected ? (
        <ErrorPage
            errorText={errorState.errorMessage}
            logo={snsLogoResult.data || ''}
            title={name}
            hasFullWidth={hasFullWidth}
        />
    ) : (
        renderElement()
    );
};
