import { Box, CardContent, Typography } from '@mui/material';

type DefaultDetailsParams = Readonly<{
    imageComponent: Readonly<JSX.Element>;
    detailsText: string;
    fontColor: string;
    hasFullWidth: boolean;
}>;

const DefaultDetails = ({
    imageComponent,
    detailsText,
    fontColor,
    hasFullWidth
}: DefaultDetailsParams): JSX.Element => (
    <Box
        sx={{
            display: 'flex',
            height: '75%',
            overflow: 'hidden',
            paddingLeft: '16px',
            paddingBottom: '16px'
        }}
    >
        <Box sx={{ flex: '30%', paddingTop: '3%' }}>{imageComponent}</Box>
        <Box sx={{ flex: '70%' }}>
            <CardContent sx={{ paddingTop: '5%' }}>
                <Typography
                    sx={{
                        height: '100%',
                        fontSize: hasFullWidth ? '2.5vw' : '5vh', // 0.05*widget-height
                        fontWeight: 200,
                        color: fontColor,
                        whiteSpace: 'pre-line'
                    }}
                >
                    {detailsText}
                </Typography>
            </CardContent>
        </Box>
    </Box>
);

export default DefaultDetails;
