import { Either, chain, fromPredicate, left, right } from 'fp-ts/lib/Either';
import * as J from 'fp-ts/Json';
import * as S from 'fp-ts/string';
import { flow } from 'fp-ts/function';

import { WidgetConfig, isWidgetConfig } from '../types/widget-config';

const validateWidgetConfig = (
    widgetConfig: unknown
): Either<unknown, WidgetConfig> =>
    isWidgetConfig(widgetConfig)
        ? right(widgetConfig)
        : left(new Error('Invalid Widget Config'));

export const parseWidgetConfigAttribute = flow(
    fromPredicate(S.isString, (x) => new Error(`${x} is not a string`)),
    chain(J.parse),
    chain(validateWidgetConfig)
);
