import { ReactNode, useEffect, useState } from 'react';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
import { Avatar, Box, CardMedia, Grid, Stack } from '@mui/material';
import FavoriteIcon from '@mui/icons-material/Favorite';
import GlobalStyles from '../assets/styles/global-styles';
import { SnsPost } from '../types/sns-post';
import { StyledText } from '../utils/styled-text';
import {
    ContentBox,
    SnsCardContent,
    TopContentBox,
    BottomContentBox,
    MainBox,
    BackgroundCard,
    TitleTypography,
    CaptionTypography,
    DescriptionTypography,
    LikeCounterTypography,
    SquareContainerDivBox,
    ContainerBox
} from '../assets/styles/sns-card-styled-components';
import {
    getMediaStyle,
    centerBoxStyle,
    classesCss
} from '../assets/styles/sns-card-stylesheets';
import { SnsCardProps } from '../types/sns-card-types';
import BicycleLoader from './bicycle-loader';
import { PostAnimationType } from '../constants';
import IntroLoader from './intro-loader';

dayjs.extend(relativeTime);

const SquareContainer = ({
    width,
    children
}: {
    width: string;
    children: ReactNode;
}): JSX.Element => (
    <SquareContainerDivBox component="div" width={width}>
        {children}
    </SquareContainerDivBox>
);

const SocialMediaLogo = ({
    src,
    width
}: {
    src?: string;
    width: string;
}): JSX.Element => (
    <SquareContainer width={width}>
        <Avatar sx={centerBoxStyle} variant="square" alt="SNS" src={src}>
            S
        </Avatar>
    </SquareContainer>
);

const Header = ({
    snsPost,
    hasFullWidth
}: {
    snsPost: SnsPost;
    hasFullWidth: boolean;
}): JSX.Element => {
    const headerText = snsPost.user.name ? snsPost.user.name : snsPost.hashtag;
    const avatarDimension = hasFullWidth ? '6.5vw' : '13vh'; // 0.13*widget-height
    const headerGap = hasFullWidth ? '2.5vw' : '5vh'; // 0.05*widget-height

    return (
        <Stack direction="row" alignItems="center" gap={headerGap}>
            {snsPost.user.name && snsPost.user.profileImageSrc && (
                <Avatar
                    src={snsPost.user.profileImageSrc}
                    sx={{
                        width: avatarDimension,
                        height: avatarDimension
                    }}
                />
            )}
            <Stack direction="column" spacing={0}>
                <TitleTypography variant="h5" hasFullWidth={hasFullWidth}>
                    {headerText}
                </TitleTypography>
                <CaptionTypography
                    variant="caption"
                    color="text.secondary"
                    hasFullWidth={hasFullWidth}
                >
                    {dayjs(snsPost.created).fromNow()}
                </CaptionTypography>
            </Stack>
        </Stack>
    );
};

const SnsCard = ({
    data,
    styleModification = {},
    isInTransition,
    hasFullWidth = false,
    hideImg = true,
    animation,
    showThumbnail
}: SnsCardProps): JSX.Element => {
    const [styledText, setStyledText] = useState<ReactNode>([]);
    const iconDimension = hasFullWidth ? '3vw' : '6vh'; // 0.06*widget-height

    const isVideo =
        data.status !== 'loading' && data.snsPost.media.type === 'VIDEO';

    useEffect(() => {
        if (data.status === 'success') {
            setStyledText(StyledText(data.snsPost.text));
        }
    }, [data.status === 'success' && data.snsPost.id]);

    return (
        <ContainerBox data={data} styleModification={styleModification}>
            <BackgroundCard styleModification={{}}>
                {data.status === 'loading' ? (
                    <IntroLoader
                        spinnerDimension={
                            hasFullWidth
                                ? { value: 7, unit: 'vw' }
                                : { value: 14, unit: 'vh' }
                        }
                    />
                ) : (
                    <>
                        <style>{classesCss(hasFullWidth)}</style>
                        <GlobalStyles />
                        <Grid container columns={13}>
                            <Grid item className="sns-card-left">
                                <MainBox>
                                    {(animation && animation.type) ===
                                        PostAnimationType.translationX && (
                                        <BicycleLoader
                                            key="vehicle"
                                            active={isVideo && isInTransition}
                                            hasFullWidth={hasFullWidth}
                                        />
                                    )}
                                    <Box>
                                        {hideImg ||
                                        (isVideo && !showThumbnail) ? null : (
                                            <CardMedia
                                                sx={{
                                                    ...getMediaStyle(
                                                        data.snsPost.media.type,
                                                        true
                                                    )
                                                }}
                                                component="img"
                                                aria-label="snsImg"
                                                src={
                                                    isVideo
                                                        ? data.snsPost
                                                              .thumbnailUrl
                                                        : data.snsPost.media
                                                              .fileSrc
                                                }
                                            />
                                        )}
                                    </Box>
                                </MainBox>
                            </Grid>

                            <Grid item className="sns-card-right">
                                {/* <Grid item xs={13} sm={6} sx={{ height: { xs: '50%', sm: '100%' } }} px="4%"> */}
                                <TopContentBox>
                                    <BottomContentBox>
                                        <Header
                                            snsPost={data.snsPost}
                                            hasFullWidth={hasFullWidth}
                                        />
                                    </BottomContentBox>
                                    <SnsCardContent className="sns-card-content">
                                        <DescriptionTypography
                                            variant="body1"
                                            hasFullWidth={hasFullWidth}
                                        >
                                            {styledText}
                                        </DescriptionTypography>
                                    </SnsCardContent>
                                </TopContentBox>
                                <ContentBox hasFullWidth={hasFullWidth}>
                                    <Stack
                                        direction="row"
                                        alignItems="center"
                                        spacing={2}
                                    >
                                        <FavoriteIcon
                                            sx={{
                                                color: '#EC4040',
                                                width: iconDimension,
                                                height: iconDimension
                                            }}
                                        />
                                        <LikeCounterTypography
                                            variant="h6"
                                            hasFullWidth={hasFullWidth}
                                        >
                                            {data.snsPost.likeCount}
                                        </LikeCounterTypography>
                                    </Stack>
                                    <SocialMediaLogo
                                        src={data.logo}
                                        width={iconDimension}
                                    />
                                </ContentBox>
                            </Grid>
                        </Grid>
                    </>
                )}
            </BackgroundCard>
        </ContainerBox>
    );
};

// eslint-disable-next-line functional/immutable-data
SnsCard.displayName = 'SnsCard';

export default SnsCard;
