export type Api = {
    baseUrl: string;
    logoUrl: string;
    authToken: string;
};

export const isApi = (value: unknown): value is Api =>
    !!value &&
    typeof value === 'object' &&
    typeof (value as Api).baseUrl === 'string' &&
    ((value as Api).logoUrl === undefined ||
        typeof (value as Api).logoUrl === 'string') &&
    typeof (value as Api).authToken === 'string';
