const localStorageKey = 'snsLogo';

export const getLogoFromLocalStorage = (): string | undefined => {
    const logoBase64 = window.localStorage.getItem(localStorageKey);

    if (!logoBase64) return undefined;

    return logoBase64;
};

export const storeLogoInLocalStorage = (logo: string): void => {
    localStorage.setItem(localStorageKey, logo);
};
